1	package govflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"reflect"
13		"sort"
14		"strconv"
15		"strings"
16		"sync"
17		"syscall"
18	)
19	
20	// 资金库状态文件相关错误。
21	var (
22		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
23		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
24		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
25		ErrStateCorrupt = errors.New("treasury state file is corrupt")
26		// ErrProposalNotFound：按编号查询或执行时提案不存在。
27		ErrProposalNotFound = errors.New("proposal not found")
28		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
29		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
30		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
31		ErrInvalidRegistration = errors.New("invalid registration")
32	)
33	
34	const (
35		stateMagic   = "govflow-treasury-state"
36		stateVersion = 1
37		lockSuffix   = ".lock"
38	)
39	
40	// BalanceUpdate 记录一个账户在一次动作前后的余额。
41	type BalanceUpdate struct {
42		Account string `json:"account"`
43		Before  int64  `json:"before"`
44		After   int64  `json:"after"`
45	}
46	
47	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
48	// 以及该动作引发的资金库与收款账户余额变动。
49	type ActionReceipt struct {
50		Index     int           `json:"index"`
51		Action    string        `json:"action"`
52		Treasury  BalanceUpdate `json:"treasury"`
53		Recipient BalanceUpdate `json:"recipient"`
54	}
55	
56	// Receipt 是一项提案首次成功执行后生成的执行凭据。
57	// 一项提案只允许成功一次；重试返回同一份凭据。
58	type Receipt struct {
59		ProposalID string          `json:"proposal_id"`
60		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
61		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
62		Actions    []ActionReceipt `json:"actions"`
63	}
64	
65	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
66	type ProposalRecord struct {
67		ID          string   `json:"id"`
68		State       string   `json:"state"`
69		TimelockEnd int64    `json:"timelock_end"`
70		Actions     []string `json:"actions"`
71	}
72	
73	// ---- 磁盘结构（JSON） ----
74	
75	type storedProposal struct {
76		ID          string   `json:"id"`
77		State       string   `json:"state"`
78		TimelockEnd int64    `json:"timelock_end"`
79		Actions     []string `json:"actions"`
80	}
81	
82	type storedState struct {
83		Magic           string                         `json:"magic"`
84		Version         int                            `json:"version"`
85		InitialTreasury int64                          `json:"initial_treasury"`
86		Treasury        int64                          `json:"treasury"`
87		Balances        map[string]int64               `json:"balances"`
88		Proposals       map[string]*storedProposal     `json:"proposals"`
89		Receipts        []*Receipt                     `json:"receipts"`
90		VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
91	}
92	
93	// Store 是绑定到单个本地状态文件的资金库句柄。
94	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
95	// 通过进程内互斥锁与文件锁（flock）串行化。
96	type Store struct {
97		path   string
98		mu     sync.Mutex // 保护本句柄上的全部操作
99		lockFD *os.File   // 跨进程文件锁
100		closed bool
101	}
102	
103	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
104	var (
105		pathLocksMu sync.Mutex
106		pathLocks   = map[string]*sync.Mutex{}
107	)
108	
109	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
110	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
111	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
112	func canonicalPath(path string) (string, error) {
113		return filepath.Abs(path)
114	}
115	
116	func inProcessLock(path string) *sync.Mutex {
117		pathLocksMu.Lock()
118		defer pathLocksMu.Unlock()
119		m, ok := pathLocks[path]
120		if !ok {
121			m = &sync.Mutex{}
122			pathLocks[path] = m
123		}
124		return m
125	}
126	
127	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
128	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
129	// treasury 必须落在有符号 64 位整数范围内且不得为负。
130	func InitTreasury(path string, treasury int64) (*Store, error) {
131		if treasury < 0 {
132			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
133		}
134		path, err := canonicalPath(path)
135		if err != nil {
136			return nil, err
137		}
138		pathMu := inProcessLock(path)
139		pathMu.Lock()
140		defer pathMu.Unlock()
141	
142		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
143		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
144		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
145		if err != nil {
146			return nil, err
147		}
148		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
149			_ = lockFD.Close()
150			return nil, err
151		}
152		// O_EXCL 保证与并发初始化竞争时只有一方成功。
153		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
154		if err != nil {
155			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
156			_ = lockFD.Close()
157			if errors.Is(err, fs.ErrExist) {
158				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
159			}
160			return nil, err
161		}
162		_ = fd.Close()
163	
164		store := &Store{path: path, lockFD: lockFD}
165		if err := store.commitLocked(newStoredState(treasury)); err != nil {
166			_ = store.funlock()
167			_ = lockFD.Close()
168			_ = os.Remove(path)
169			return nil, err
170		}
171		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
172		if err := store.funlock(); err != nil {
173			_ = lockFD.Close()
174			_ = os.Remove(path)
175			return nil, err
176		}
177		return store, nil
178	}
179	
180	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
181	func Open(path string) (*Store, error) {
182		path, err := canonicalPath(path)
183		if err != nil {
184			return nil, err
185		}
186		pathMu := inProcessLock(path)
187		pathMu.Lock()
188		defer pathMu.Unlock()
189		return openStoreHoldingPathLock(path)
190	}
191	
192	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
193	func openStoreHoldingPathLock(path string) (*Store, error) {
194		if _, err := os.Stat(path); err != nil {
195			return nil, err
196		}
197		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
198		if err != nil {
199			return nil, err
200		}
201		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
202			_ = lockFD.Close()
203			return nil, err
204		}
205		store := &Store{path: path, lockFD: lockFD}
206		if _, err := store.loadLocked(); err != nil {
207			_ = store.funlock()
208			_ = lockFD.Close()
209			return nil, err
210		}
211		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
212		if err := store.funlock(); err != nil {
213			_ = lockFD.Close()
214			return nil, err
215		}
216		return store, nil
217	}
218	
219	// Path 返回状态文件路径。
220	func (s *Store) Path() string { return s.path }
221	
222	// Close 释放文件锁。关闭后其它操作返回错误。
223	func (s *Store) Close() error {
224		s.mu.Lock()
225		defer s.mu.Unlock()
226		if s.closed {
227			return nil
228		}
229		s.closed = true
230		if err := s.funlock(); err != nil {
231			_ = s.lockFD.Close()
232			return err
233		}
234		return s.lockFD.Close()
235	}
236	
237	func (s *Store) flock(how int) error {
238		if s.lockFD == nil {
239			return errors.New("treasury store is closed")
240		}
241		return syscall.Flock(int(s.lockFD.Fd()), how)
242	}
243	
244	func (s *Store) funlock() error {
245		if s.lockFD == nil {
246			return nil
247		}
248		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
249	}
250	
251	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
252	// 返回的 commit 在操作结束时释放锁。
253	func (s *Store) begin() (func(), error) {
254		pathMu := inProcessLock(s.path)
255		pathMu.Lock()
256		s.mu.Lock()
257		if s.closed {
258			s.mu.Unlock()
259			pathMu.Unlock()
260			return nil, errors.New("treasury store is closed")
261		}
262		if err := s.flock(syscall.LOCK_EX); err != nil {
263			s.mu.Unlock()
264			pathMu.Unlock()
265			return nil, err
266		}
267		return func() {
268			_ = s.funlock()
269			s.mu.Unlock()
270			pathMu.Unlock()
271		}, nil
272	}
273	
274	func newStoredState(treasury int64) *storedState {
275		return &storedState{
276			Magic:           stateMagic,
277			Version:         stateVersion,
278			InitialTreasury: treasury,
279			Treasury:        treasury,
280			Balances:        map[string]int64{},
281			Proposals:       map[string]*storedProposal{},
282			Receipts:        []*Receipt{},
283			VoteProposals:   map[string]*storedVoteProposal{},
284		}
285	}
286	
287	// ---- 登记 ----
288	
289	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
290	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
291	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
292	// 内容不同则返回 ErrProposalConflict。
293	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
294		if id == "" {
295			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
296		}
297		commit, err := s.begin()
298		if err != nil {
299			return false, err
300		}
301		defer commit()
302	
303		state, err := s.loadLocked()
304		if err != nil {
305			return false, err
306		}
307		stored := copyActions(actions)
308		if existing, ok := state.Proposals[id]; ok {
309			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
310				return true, nil
311			}
312			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
313		}
314		// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
315		if vp, ok := state.VoteProposals[id]; ok {
316			return false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
317		}
318		state.Proposals[id] = &storedProposal{
319			ID:          id,
320			State:       "passed",
321			TimelockEnd: timelockEnd,
322			Actions:     stored,
323		}
324		if err := s.commitLocked(state); err != nil {
325			return false, err
326		}
327		return false, nil
328	}
329	
330	func copyActions(actions []string) []string {
331		if actions == nil {
332			return nil
333		}
334		copied := make([]string, len(actions))
335		copy(copied, actions)
336		return copied
337	}
338	
339	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
340	func sameActions(a, b []string) bool {
341		if len(a) != len(b) {
342			return false
343		}
344		for i := range a {
345			if a[i] != b[i] {
346				return false
347			}
348		}
349		return true
350	}
351	
352	// ---- 执行 ----
353	
354	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
355	type executionTarget struct {
356		state        string
357		timelockEnd  int64
358		actions      []string
359		markExecuted func()
360	}
361	
362	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
363	func resolveExecutable(state *storedState, id string) *executionTarget {
364		if p, ok := state.Proposals[id]; ok {
365			return &executionTarget{
366				state:        p.State,
367				timelockEnd:  p.TimelockEnd,
368				actions:      p.Actions,
369				markExecuted: func() { p.State = "executed" },
370			}
371		}
372		if vp, ok := state.VoteProposals[id]; ok {
373			return &executionTarget{
374				state:        vp.State,
375				timelockEnd:  vp.TimelockEnd,
376				actions:      vp.Actions,
377				markExecuted: func() { vp.State = "executed" },
378			}
379		}
380		return nil
381	}
382	
383	// proposalOwners 将两个来源的提案编号映射到状态，供凭据重放交叉校验。
384	func proposalOwnerState(state *storedState, id string) (string, []string, bool) {
385		if p, ok := state.Proposals[id]; ok {
386			return p.State, p.Actions, true
387		}
388		if vp, ok := state.VoteProposals[id]; ok {
389			return vp.State, vp.Actions, true
390		}
391		return "", nil, false
392	}
393	
394	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
395	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
396	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
397	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
398	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
399	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
400		commit, err := s.begin()
401		if err != nil {
402			return nil, err
403		}
404		defer commit()
405	
406		state, err := s.loadLocked()
407		if err != nil {
408			return nil, err
409		}
410		target := resolveExecutable(state, id)
411		if target == nil {
412			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
413		}
414		if target.state == "executed" {
415			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
416				return cloneReceipt(rcpt), nil
417			}
418			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
419		}
420		if target.state != "passed" {
421			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
422		}
423		if now < target.timelockEnd {
424			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
425		}
426		if len(target.actions) == 0 {
427			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
428		}
429	
430		// 第一阶段：在副本上校验并预演全部动作。任何一步失败都不得落盘。
431		type step struct {
432			account        string
433			amount         int64
434			treasuryBefore int64
435			treasuryAfter  int64
436			accountBefore  int64
437			accountAfter   int64
438		}
439		simTreasury := state.Treasury
440		simBalances := map[string]int64{}
441		for k, v := range state.Balances {
442			simBalances[k] = v
443		}
444		steps := make([]step, 0, len(target.actions))
445		for i, raw := range target.actions {
446			account, amount, perr := ParseTransfer(raw)
447			if perr != nil {
448				// 双 %w：调用方既可按 ErrExecutionRejected 判定执行被拒，
449				// 也可按 ErrInvalidAction 区分“动作格式错误”这一具体原因。
450				return nil, fmt.Errorf("%w: action %d (%q): %w", ErrExecutionRejected, i, raw, perr)
451			}
452			balanceBefore := simBalances[account]
453			balanceAfter, ok := addInt64(balanceBefore, amount)
454			if !ok {
455				return nil, execReject(fmt.Sprintf("recipient balance overflow at action %d: account=%s balance=%d amount=%d", i, account, balanceBefore, amount))
456			}
457			if simTreasury < amount {
458				return nil, execReject(fmt.Sprintf("insufficient treasury balance at action %d: treasury=%d amount=%d", i, simTreasury, amount))
459			}
460			treasuryBefore := simTreasury
461			simTreasury -= amount
462			simBalances[account] = balanceAfter
463			steps = append(steps, step{
464				account:        account,
465				amount:         amount,
466				treasuryBefore: treasuryBefore,
467				treasuryAfter:  simTreasury,
468				accountBefore:  balanceBefore,
469				accountAfter:   balanceAfter,
470			})
471		}
472	
473		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
474		receipt := &Receipt{
475			ProposalID: id,
476			ExecutedAt: now,
477			Order:      len(state.Receipts),
478			Actions:    make([]ActionReceipt, 0, len(steps)),
479		}
480		for i, st := range steps {
481			receipt.Actions = append(receipt.Actions, ActionReceipt{
482				Index:  i,
483				Action: target.actions[i],
484				Treasury: BalanceUpdate{
485					Account: "treasury",
486					Before:  st.treasuryBefore,
487					After:   st.treasuryAfter,
488				},
489				Recipient: BalanceUpdate{
490					Account: st.account,
491					Before:  st.accountBefore,
492					After:   st.accountAfter,
493				},
494			})
495		}
496		state.Treasury = simTreasury
497		state.Balances = simBalances
498		target.markExecuted()
499		state.Receipts = append(state.Receipts, receipt)
500	
501		if err := s.commitLocked(state); err != nil {
502			return nil, err
503		}
504		return cloneReceipt(receipt), nil
505	}
506	
507	func findReceipt(receipts []*Receipt, id string) *Receipt {
508		for _, r := range receipts {
509			if r.ProposalID == id {
510				return r
511			}
512		}
513		return nil
514	}
515	
516	func cloneReceipt(r *Receipt) *Receipt {
517		if r == nil {
518			return nil
519		}
520		copied := *r
521		if r.Actions != nil {
522			copied.Actions = make([]ActionReceipt, len(r.Actions))
523			copy(copied.Actions, r.Actions)
524		}
525		return &copied
526	}
