684	// ---- 持久化 ----
685	
686	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
687	func (s *Store) loadLocked() (*storedState, error) {
688		raw, err := os.ReadFile(s.path)
689		if err != nil {
690			return nil, err
691		}
692		if len(bytes.TrimSpace(raw)) == 0 {
693			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
694		}
695		if err := checkStateStructure(raw); err != nil {
696			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
697		}
698		var state storedState
699		dec := json.NewDecoder(bytes.NewReader(raw))
700		dec.DisallowUnknownFields()
701		if err := dec.Decode(&state); err != nil {
702			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
703		}
704		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
705		var extra json.RawMessage
706		if err := dec.Decode(&extra); err != io.EOF {
707			if err == nil {
708				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
709			}
710			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
711		}
712		if err := validateState(&state); err != nil {
713			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
714		}
715		return &state, nil
716	}
717	
718	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
719	// 任一步失败都保留上次完整状态。调用方必须持锁。
720	func (s *Store) commitLocked(state *storedState) error {
721		if err := validateState(state); err != nil {
722			return fmt.Errorf("refusing to persist invalid state: %w", err)
723		}
724		payload, err := json.MarshalIndent(state, "", "  ")
725		if err != nil {
726			return err
727		}
728		payload = append(payload, '\n')
729	
730		dir := filepath.Dir(s.path)
731		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
732		if err != nil {
733			return err
734		}
735		tmpName := tmp.Name()
736		cleanup := func() { _ = os.Remove(tmpName) }
737		if _, err := tmp.Write(payload); err != nil {
738			_ = tmp.Close()
739			cleanup()
740			return err
741		}
742		if err := tmp.Sync(); err != nil {
743			_ = tmp.Close()
744			cleanup()
745			return err
746		}
747		if err := tmp.Close(); err != nil {
748			cleanup()
749			return err
750		}
751		if err := os.Chmod(tmpName, 0o600); err != nil {
752			cleanup()
753			return err
754		}
755		if err := os.Rename(tmpName, s.path); err != nil {
756			cleanup()
757			return err
758		}
759		if err := syncDir(dir); err != nil {
760			return err
761		}
762		return nil
763	}
764	
765	func syncDir(dir string) error {
766		d, err := os.Open(dir)
767		if err != nil {
768			return err
769		}
770		defer d.Close()
771		return d.Sync()
772	}
773	
774	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
775	func validateState(state *storedState) error {
776		if state.Magic != stateMagic {
777			return fmt.Errorf("bad magic %q", state.Magic)
778		}
779		if state.Version != stateVersion {
780			return fmt.Errorf("unsupported state version %d", state.Version)
781		}
782		if state.InitialTreasury < 0 {
783			return errors.New("initial treasury balance is negative")
784		}
785		if state.Treasury < 0 {
786			return errors.New("treasury balance is negative")
787		}
788		if state.Balances == nil {
789			return errors.New("balances table is missing")
790		}
791		if state.Proposals == nil {
792			return errors.New("proposals table is missing")
793		}
794		if state.Receipts == nil {
795			return errors.New("receipts table is missing")
796		}
797		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
798		if state.VoteProposals == nil {
799			state.VoteProposals = map[string]*storedVoteProposal{}
800		}
801		for account, balance := range state.Balances {
802			if account == "" {
803				return errors.New("balance entry with empty account")
804			}
805			if balance < 0 {
806				return fmt.Errorf("balance of %q is negative", account)
807			}
808		}
809		for key, p := range state.Proposals {
810			if p == nil {
811				return fmt.Errorf("proposal %q is empty", key)
812			}
813			if p.ID != key || p.ID == "" {
814				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
815			}
816			if p.State != "passed" && p.State != "executed" {
817				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
818			}
819			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
820		}
821		if err := validateVoteProposals(state); err != nil {
822			return err
823		}
824	
825		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
826		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
827		simTreasury := state.InitialTreasury
828		simBalances := map[string]int64{}
829		seenReceipts := map[string]int{}
830		for order, rcpt := range state.Receipts {
831			if rcpt == nil {
832				return fmt.Errorf("receipt %d is empty", order)
833			}
834			if rcpt.Order != order {
835				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
836			}
837			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
838				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
839			}
840			seenReceipts[rcpt.ProposalID] = order
841			ownerState, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
842			if !found {
843				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
844			}
845			if ownerState != "executed" {
846				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
847			}
848			if len(rcpt.Actions) != len(ownerActions) {
849				return fmt.Errorf("receipt %q action count %d does not match proposal %d", rcpt.ProposalID, len(rcpt.Actions), len(ownerActions))
850			}
851			for i, ar := range rcpt.Actions {
852				if ar.Index != i {
853					return fmt.Errorf("receipt %q action %d has index %d", rcpt.ProposalID, i, ar.Index)
854				}
855				if ar.Action != ownerActions[i] {
856					return fmt.Errorf("receipt %q action %d text does not match registered action", rcpt.ProposalID, i)
857				}
858				account, amount, err := ParseTransfer(ar.Action)
859				if err != nil {
860					return fmt.Errorf("receipt %q action %d is not executable: %v", rcpt.ProposalID, i, err)
861				}
862				if ar.Treasury.Account != "treasury" || ar.Treasury.Before != simTreasury {
863					return fmt.Errorf("receipt %q action %d treasury before-balance mismatch", rcpt.ProposalID, i)
864				}
865				if simTreasury < amount || ar.Treasury.After != simTreasury-amount {
866					return fmt.Errorf("receipt %q action %d treasury after-balance mismatch", rcpt.ProposalID, i)
867				}
868				before := simBalances[account]
869				if ar.Recipient.Account != account || ar.Recipient.Before != before {
870					return fmt.Errorf("receipt %q action %d recipient before-balance mismatch", rcpt.ProposalID, i)
871				}
872				after, ok := addInt64(before, amount)
873				if !ok || ar.Recipient.After != after {
874					return fmt.Errorf("receipt %q action %d recipient after-balance mismatch", rcpt.ProposalID, i)
875				}
876				simTreasury -= amount
877				simBalances[account] = after
878			}
879		}
880		if simTreasury != state.Treasury {
881			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
882		}
883		if len(simBalances) != len(state.Balances) {
884			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
885		}
886		for account, balance := range state.Balances {
887			if simBalances[account] != balance {
888				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
889			}
890		}
891		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
892		for _, p := range state.Proposals {
893			_, hasReceipt := seenReceipts[p.ID]
894			if p.State == "executed" && !hasReceipt {
895				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
896			}
897		}
898		for _, p := range state.VoteProposals {
899			_, hasReceipt := seenReceipts[p.ID]
900			if p.State == "executed" && !hasReceipt {
901				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
902			}
903		}
904		return nil
905	}
906	
907	// ---- 结构检查：固定字段名逐字匹配 + 重复键拒绝 ----
908	
909	// schemaKind 是状态文件 JSON 在某一层的形状类别。
910	type schemaKind int
911	
912	const (
913		kindAny     schemaKind = iota // 叶子值：结构检查不深入，类型由解码器核对
914		kindObject                    // 固定字段对象：键必须与保存格式的字段名逐字一致
915		kindMap                       // 业务编号表：键是自由文本（账户名、提案编号）
916		kindArray                     // 数组
917		kindString                    // 叶子：必须是 JSON 字符串
918		kindBoolean                   // 叶子：必须是 JSON 布尔值（不接受字符串/数字/null）
919		kindInteger                   // 叶子：必须是 int64 范围内的 JSON 整数（不接受小数/指数/字符串/null）
920	)
921	
922	// schemaNode 描述状态文件某一层允许的形状。整棵树由 storedState 的 json tag
923	// 反射生成，字段名集合因此永远与保存格式一致，不会随结构演进而漂移。
924	type schemaNode struct {
925		kind   schemaKind
926		fields map[string]*schemaNode // kindObject：字段名 → 值的形状
927		elem   *schemaNode            // kindMap/kindArray：值/元素的形状
928	}
929	
930	// schemaOf 按 encoding/json 的字段名规则（json tag 优先，缺省用字段名）推导形状。
931	func schemaOf(t reflect.Type) *schemaNode {
932		for t.Kind() == reflect.Pointer {
933			t = t.Elem()
934		}
935		switch t.Kind() {
936		case reflect.Struct:
937			node := &schemaNode{kind: kindObject, fields: map[string]*schemaNode{}}
938			for i := 0; i < t.NumField(); i++ {
939				f := t.Field(i)
940				if f.PkgPath != "" { // 未导出字段不参与 JSON
941					continue
942				}
943				name := f.Name
944				if tag, ok := f.Tag.Lookup("json"); ok {
945					tagName, _, _ := strings.Cut(tag, ",")
946					if tagName == "-" {
947						continue
948					}
949					if tagName != "" {
950						name = tagName
951					}
952				}
953				node.fields[name] = schemaOf(f.Type)
954			}
955			return node
956		case reflect.Map:
957			return &schemaNode{kind: kindMap, elem: schemaOf(t.Elem())}
958		case reflect.Slice, reflect.Array:
959			return &schemaNode{kind: kindArray, elem: schemaOf(t.Elem())}
960		case reflect.String:
961			return &schemaNode{kind: kindString}
962		case reflect.Bool:
963			return &schemaNode{kind: kindBoolean}
964		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64,
965			reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
966			return &schemaNode{kind: kindInteger}
967		default:
968			return &schemaNode{kind: kindAny}
969		}
970	}
971	
972	var storedStateSchema = schemaOf(reflect.TypeOf(storedState{}))
973	
974	func init() {
975		// 票据的四个标量字段（representative/weight/support/voted_at）由
976		// validateStoredBallot 逐票判定“缺失/空值/类型不符”，其错误原因需要带上
977		// 提案编号、票据下标与字段名；因此结构扫描在这些叶子位置保持宽松（kindAny），
978		// 不抢在解码器之前用不含票据定位的通用信息报错。
979		ballotFields := storedStateSchema.fields["vote_proposals"].elem.fields["ballots"].elem.fields
980		for _, name := range []string{"representative", "weight", "support", "voted_at"} {
981			ballotFields[name].kind = kindAny
982		}
983	}
984	
985	// scanFrame 是结构扫描的栈帧。
986	type scanFrame struct {
987		node    *schemaNode
988		isArray bool
989		opaque  bool // 形状不符或叶子位置的容器：只配对括号，类型错误交给解码器报告
990		seen    map[string]bool
991		atValue bool // 对象帧：下一个待消费 token 是值而非键
992		index   int  // 数组帧：下一个元素下标
993		path    string
994	}
995	
996	func peekFrame(stack []*scanFrame) *scanFrame {
997		if len(stack) == 0 {
998			return nil
999		}
1000		return stack[len(stack)-1]
1001	}
1002	
1003	// checkStateStructure 在解码前逐 token 扫描状态文件：
1004	//   - 同一对象内键（按 JSON 解读后的字符串，转义拼写与普通拼写视为同一键）不得重复；
1005	//   - 固定字段对象的键必须与保存格式的字段名逐字一致：大小写变体（如 Treasury、
1006	//     Support）与未知字段一样拒绝，避免解码器的大小写折叠把两份值并入同一字段；
1007	//   - balances/proposals/vote_proposals 等业务编号表的键是自由文本，
1008	//     Audit 与 audit、GIP-1 与 gip-1 是不同账户/编号，不做字段名检查。
1009	//
1010	// 报错带有出问题的字段与所在记录的路径（如 vote_proposals["GIP-1"].ballots[0]），
1011	// 便于定位。字段顺序、缩进与合法转义不影响判定。
1012	func checkStateStructure(raw []byte) error {
1013		dec := json.NewDecoder(bytes.NewReader(raw))
1014		// UseNumber：数字 token 保留词面写法，整数叶子可据此精确判定 int64 范围，
1015		// 不被 float64 在 2^63 附近的舍入混淆（MaxInt64 与 MaxInt64+1 会折成同一浮点）。
1016		dec.UseNumber()
1017		var stack []*scanFrame
1018		// 对象帧读到键时，把该键对应值的形状与路径暂存于此，供紧随其后的值使用。
1019		pendingNode := storedStateSchema
1020		pendingPath := "state"
1021	
1022		// 一个值消费完毕：推进父帧的键/值位置或数组下标。
1023		finishValue := func() {
1024			top := peekFrame(stack)
1025			if top == nil || top.opaque {
1026				return
1027			}
1028			if top.isArray {
1029				top.index++
1030			} else {
1031				top.atValue = false
1032			}
1033		}
1034	
1035		for {
1036			tok, err := dec.Token()
1037			if err == io.EOF {
1038				if len(stack) != 0 {
1039					return errors.New("unterminated object or array")
1040				}
1041				return nil
1042			}
1043			if err != nil {
1044				return err
1045			}
1046	
1047			if top := peekFrame(stack); top != nil && top.opaque {
1048				// 不透明容器内不做字段检查，只配对括号。
1049				if d, ok := tok.(json.Delim); ok {
1050					if d == '{' || d == '[' {
1051						stack = append(stack, &scanFrame{opaque: true})
1052					} else {
1053						stack = stack[:len(stack)-1]
1054						finishValue()
1055					}
1056				}
1057				continue
1058			}
1059	
1060			if top := peekFrame(stack); top != nil && !top.isArray && !top.atValue {
1061				// 对象帧的键位置：闭括号或下一个键。
1062				if d, ok := tok.(json.Delim); ok {
1063					if d != '}' {
1064						return fmt.Errorf("unexpected %q inside object at %s", string(d), top.path)
1065					}
1066					stack = stack[:len(stack)-1]
1067					finishValue()
1068					continue
1069				}
1070				key, ok := tok.(string)
1071				if !ok {
1072					return errors.New("object key must be a string")
1073				}
1074				if top.seen[key] {
1075					return fmt.Errorf("duplicate key %q at %s", key, top.path)
1076				}
1077				top.seen[key] = true
1078				top.atValue = true
1079				switch top.node.kind {
1080				case kindObject:
1081					child, known := top.node.fields[key]
1082					if !known {
1083						return fmt.Errorf("unknown field %q at %s", key, top.path)
1084					}
1085					pendingNode = child
1086					pendingPath = top.path + "." + key
1087				case kindMap:
1088					// 业务编号是自由文本，大小写变体属于不同编号，不得拒绝或合并。
1089					pendingNode = top.node.elem
1090					pendingPath = top.path + "[" + strconv.Quote(key) + "]"
1091				}
1092				continue
1093			}
1094	
1095			// 值位置：对象键之后的值或数组元素。
1096			node := pendingNode
1097			path := pendingPath
1098			if top := peekFrame(stack); top != nil && top.isArray {
1099				node = top.node.elem
1100				path = top.path + "[" + strconv.Itoa(top.index) + "]"
1101			}
1102			if d, ok := tok.(json.Delim); ok {
1103				switch d {
1104				case '{', '[':
1105					frame := &scanFrame{isArray: d == '[', path: path}
1106					shapeOK := (d == '{' && (node.kind == kindObject || node.kind == kindMap)) ||
1107						(d == '[' && node.kind == kindArray)
1108					if !shapeOK {
1109						// 叶子位置出现容器或形状不符：跳过内容，类型错误由解码器报告。
1110						frame.opaque = true
1111					} else {
1112						frame.node = node
1113						if d == '{' {
1114							frame.seen = map[string]bool{}
1115						}
1116					}
1117					stack = append(stack, frame)
1118				default: // '}' 或 ']'：数组结束（对象的闭括号已在键位置处理）
1119					if len(stack) == 0 {
1120						return errors.New("unexpected closing delimiter")
1121					}
1122					stack = stack[:len(stack)-1]
1123					finishValue()
1124				}
1125				continue
1126			}
1127			// 标量值（含 null）：严格叶子必须与字段声明的 JSON 类型逐字一致，
1128			// null 不允许用来顶替字符串/布尔/整数。
1129			if err := checkLeafScalar(node, path, tok); err != nil {
1130				return err
1131			}
1132			finishValue()
1133		}
1134	}
1135	
1136	// leafKindName 是严格叶子类型在错误信息中的人类可读名称。
1137	func leafKindName(k schemaKind) string {
1138		switch k {
1139		case kindString:
1140			return "string"
1141		case kindBoolean:
1142			return "boolean"
1143		case kindInteger:
1144			return "integer"
1145		default:
1146			return "value"
1147		}
1148	}
1149	
1150	// tokenKindName 归类一个标量 token 实际写出的 JSON 类型。
1151	func tokenKindName(tok json.Token) string {
1152		switch v := tok.(type) {
1153		case nil:
1154			return "null"
1155		case string:
1156			return "string"
1157		case bool:
1158			return "boolean"
1159		case json.Number:
1160			if _, err := strconv.ParseInt(string(v), 10, 64); err == nil {
1161				return "integer"
1162			}
1163			return "number"
1164		default:
1165			return "value"
1166		}
1167	}
1168	
1169	// checkLeafScalar 校验严格标量叶子：字符串/布尔/int64 整数位置出现 null 或
1170	// 其它 JSON 类型即判结构损坏。非整数（小数、指数）或超出 int64 的整数同样拒绝。
1171	func checkLeafScalar(node *schemaNode, path string, tok json.Token) error {
1172		switch node.kind {
1173		case kindString, kindBoolean, kindInteger:
1174		default:
1175			return nil
1176		}
1177		if node.kind == kindInteger {
1178			if n, ok := tok.(json.Number); ok {
1179				if _, err := strconv.ParseInt(string(n), 10, 64); err != nil {
1180					return fmt.Errorf("field at %s must be an int64 integer, got %s", path, string(n))
1181				}
1182				return nil
1183			}
1184		}
1185		want := leafKindName(node.kind)
1186		if got := tokenKindName(tok); got != want {
1187			return fmt.Errorf("field at %s must be %s, got %s", path, want, got)
1188		}
1189		return nil
1190	}
1191

