322			fmt.Fprintf(os.Stderr, "usage error: --id and --voter are required\n")
323			os.Exit(2)
324		}
325		var support bool
326		switch *choice {
327		case "for":
328			support = true
329		case "against":
330			support = false
331		default:
332			fmt.Fprintf(os.Stderr, "usage error: --choice must be %q or %q\n", "for", "against")
333			os.Exit(2)
334		}
335		now := parseIntFlag(cf.fs, "now", *nowRaw)
336	
337		store, err := govflow.Open(cf.state)
338		if err != nil {
339			fail(err)
340		}
341		defer store.Close()
342		ballot, err := store.CastVote(*id, *voter, support, now)
343		if err != nil {
344			fail(err)
345		}
346		if cf.asJSON {
347			emitJSON(ballot)
348			return
