450		accounts := make([]string, 0, len(snapshot.Balances))
451		for acct := range snapshot.Balances {
452			accounts = append(accounts, acct)
453		}
454		sort.Strings(accounts)
455		for _, acct := range accounts {
456			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
457		}
