302	// ---- 校验与派生 ----
303	
304	type proposalSpec struct {
305		members  []VoteMember
306		weights  map[string]int64
307		delegate map[string]string // 直接委托对象
308		pathOf   map[string][]string
309		headOf   map[string]string // 最终代表
310		groupW   map[string]int64  // 最终代表名下归集的全部原始权重
311		total    int64
312	}
313	
314	// validateProposalInput 校验全部创建规则并派生委托路径与代表权重。
315	// 任何非法条件都返回错误，调用方必须整项拒绝。
316	func validateProposalInput(in *CreateVoteInput) (*proposalSpec, error) {
317		if in.ID == "" {
318			return nil, invalidProposal("proposal id must not be empty")
319		}
320		if len(in.Members) == 0 {
321			return nil, invalidProposal("proposal %s: member list must not be empty", in.ID)
322		}
323		weights := make(map[string]int64, len(in.Members))
324		order := make([]string, 0, len(in.Members))
325		for _, m := range in.Members {
326			if m.ID == "" {
327				return nil, invalidProposal("proposal %s: member id must not be empty", in.ID)
328			}
329			if _, dup := weights[m.ID]; dup {
330				return nil, invalidProposal("proposal %s: duplicate member %q", in.ID, m.ID)
331			}
332			if m.Weight <= 0 {
333				return nil, invalidProposal("proposal %s: member %q weight must be a positive integer, got %d", in.ID, m.ID, m.Weight)
334			}
335			weights[m.ID] = m.Weight
336			order = append(order, m.ID)
337		}
338	
339		// 总权重必须在 int64 范围内（各权重已为正）。
340		var total int64
341		for _, m := range in.Members {
342			sum, ok := addInt64(total, m.Weight)
343			if !ok {
344				return nil, invalidProposal("proposal %s: total member weight overflows int64", in.ID)
345			}
346			total = sum
347		}
348	
349		if in.Quorum < 1 || in.Quorum > total {
350			return nil, invalidProposal("proposal %s: quorum must be between 1 and total weight %d, got %d", in.ID, total, in.Quorum)
351		}
352		if !(0 <= in.StartAt && in.StartAt < in.Deadline && in.Deadline <= in.TimelockEnd) {
353			return nil, invalidProposal("proposal %s: times must satisfy 0 <= start < deadline <= timelock, got start=%d deadline=%d timelock=%d",
354				in.ID, in.StartAt, in.Deadline, in.TimelockEnd)
355		}
356	
357		delegate := make(map[string]string, len(in.Delegations))
358		for _, d := range in.Delegations {
359			if d.From == "" || d.To == "" {
360				return nil, invalidProposal("proposal %s: delegation members must not be empty", in.ID)
361			}
362			if _, ok := weights[d.From]; !ok {
363				return nil, invalidProposal("proposal %s: delegation from unknown member %q", in.ID, d.From)
364			}
365			if _, ok := weights[d.To]; !ok {
366				return nil, invalidProposal("proposal %s: delegation to unknown member %q", in.ID, d.To)
367			}
368			if d.From == d.To {
369				return nil, invalidProposal("proposal %s: member %q must not delegate to itself", in.ID, d.From)
370			}
371			if _, dup := delegate[d.From]; dup {
372				return nil, invalidProposal("proposal %s: member %q delegates more than once", in.ID, d.From)
373			}
374			delegate[d.From] = d.To
375		}
376	
377		// 解析每名成员的委托路径：从本人出发，沿直接委托对象逐次前行，
378		// 直到未再委托的最终代表。每个成员出度至多 1，且自委托/循环已被拦截，
379		// 所以该遍历必然终止。
380		// 命中已解析成员时必须拼接其“完整路径”（去掉与之重复的衔接点），
381		// 不能直接跳到它的最终代表，否则多跳链上的中间委托对象会丢失。
382		// 结果只依赖委托关系本身，与成员及委托参数的提交顺序无关。
383		pathOf := make(map[string][]string, len(weights))
384		headOf := make(map[string]string, len(weights))
385		for _, id := range order {
386			if _, done := headOf[id]; done {
387				continue
388			}
389			chain := []string{id}
390			onChain := map[string]int{id: 0}
391			cur := id
392			for {
393				next, has := delegate[cur]
394				if !has {
395					break // cur 即未再委托的最终代表
396				}
397				if pos, cyc := onChain[next]; cyc {
398					return nil, invalidProposal("proposal %s: delegation cycle involving %q", in.ID, chain[pos])
399				}
400				if resolved, ok := pathOf[next]; ok {
401					// 拼接已解析的完整后缀；resolved[0] == next，逐跳衔接且无重复成员。
402					chain = append(chain, resolved...)
403					cur = resolved[len(resolved)-1]
404					break
405				}
406				chain = append(chain, next)
407				onChain[next] = len(chain) - 1
408				cur = next
409			}
410			head := cur
411			// 链上每个成员的路径都是自身到 head 的后缀。命中已解析后缀时，
412			// 后缀成员均已登记，这里只补齐尚未解析的成员。
413			for i := 0; i < len(chain); i++ {
414				member := chain[i]
415				if _, ok := headOf[member]; !ok {
416					pathOf[member] = append([]string(nil), chain[i:]...)
417					headOf[member] = head
418				}
419			}
420		}
421	
422		// 归集每个最终代表名下的全部原始权重；子集和必然不超过总权重。
423		groupW := make(map[string]int64)
424		for _, id := range order {
425			head := headOf[id]
426			sum, ok := addInt64(groupW[head], weights[id])
427			if !ok {
428				return nil, invalidProposal("proposal %s: delegated weight for %q overflows int64", in.ID, head)
429			}
430			groupW[head] = sum
431		}
432	
433		return &proposalSpec{
434			members:  append([]VoteMember(nil), in.Members...),
435			weights:  weights,
436			delegate: delegate,
437			pathOf:   pathOf,
438			headOf:   headOf,
439			groupW:   groupW,
440			total:    total,
441		}, nil
442	}
443	
444	func invalidProposal(format string, args ...any) error {
445		return fmt.Errorf("%w: %s", ErrInvalidProposal, fmt.Sprintf(format, args...))
446	}
